/** One `classify_link()` input plus the backend's expected link verdict. */
data class LinkGoldenRow(
    /** Every one of these is nullable on the wire (`download_sources` columns),
     * which is exactly why the port has to survive nulls. */
    val service: String?,
    val sourceUrl: String?,
    val finalUrl: String?,
    val playbackType: String?,
    val isTemporary: Boolean?,
    val status: String?,
    val expected: String,
) {
    fun field(name: String): String {
        val prefix = name + "="
        return expected.split('|').firstOrNull { it.startsWith(prefix) }
            ?.removePrefix(prefix) ?: error("golden row has no field '$name'")
    }

    fun intField(name: String): Int = field(name).toInt()
}

